/**
 * Error de dominio del carrito. El `code` es estable y pensado para que
 * la capa HTTP (u otra) lo traduzca a una respuesta concreta.
 */
export class CartError extends Error {
  /**
   * @param {string} code
   * @param {string} message
   */
  constructor(code, message) {
    super(message);
    this.name = 'CartError';
    this.code = code;
  }
}

export const ErrorCodes = Object.freeze({
  INVALID_CART_ID: 'INVALID_CART_ID',
  INVALID_CURRENCY: 'INVALID_CURRENCY',
  INVALID_AMOUNT: 'INVALID_AMOUNT',
  INVALID_QUANTITY: 'INVALID_QUANTITY',
  INVALID_PRODUCT: 'INVALID_PRODUCT',
  CURRENCY_MISMATCH: 'CURRENCY_MISMATCH',
  CART_NOT_FOUND: 'CART_NOT_FOUND',
  CART_ALREADY_EXISTS: 'CART_ALREADY_EXISTS',
  CART_FULL: 'CART_FULL',
  QUANTITY_LIMIT_EXCEEDED: 'QUANTITY_LIMIT_EXCEEDED',
  ITEM_NOT_FOUND: 'ITEM_NOT_FOUND',
  PRODUCT_NOT_FOUND: 'PRODUCT_NOT_FOUND',
  CONCURRENCY_CONFLICT: 'CONCURRENCY_CONFLICT',
  INVALID_RULE: 'INVALID_RULE',
});

import { CartError, ErrorCodes } from './errors.js';

/**
 * Todos los importes se manejan como enteros en la unidad menor de la moneda
 * (céntimos para EUR/USD, yenes para JPY...). Nunca se usan floats para dinero.
 */

/** @param {unknown} value @param {string} [name] @returns {number} */
export function assertCents(value, name = 'amount') {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new CartError(
      ErrorCodes.INVALID_AMOUNT,
      `${name} must be a non-negative safe integer (minor units)`,
    );
  }
  return value;
}

/** @param {unknown} currency @returns {string} */
export function assertCurrency(currency) {
  if (typeof currency !== 'string' || !/^[A-Z]{3}$/.test(currency)) {
    throw new CartError(ErrorCodes.INVALID_CURRENCY, `invalid ISO 4217 currency: ${currency}`);
  }
  return currency;
}

/**
 * Número de decimales de una moneda según Intl (EUR→2, JPY→0, BHD→3...).
 * @param {string} currency
 */
export function minorUnitDigits(currency) {
  return new Intl.NumberFormat('en', { style: 'currency', currency }).resolvedOptions()
    .maximumFractionDigits;
}

/**
 * Formatea un importe en céntimos para mostrarlo al usuario.
 * @param {number} cents
 * @param {string} currency
 * @param {string} [locale]
 */
export function formatMoney(cents, currency, locale = 'es-ES') {
  const digits = minorUnitDigits(currency);
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(
    cents / 10 ** digits,
  );
}

/**
 * Aplica un porcentaje expresado en puntos básicos (1 bp = 0.01%) a un importe
 * y redondea al entero más cercano (mitad hacia arriba).
 * @param {number} amountCents
 * @param {number} bps
 */
export function applyBps(amountCents, bps) {
  return Math.round((amountCents * bps) / 10000);
}

import { CartError, ErrorCodes } from './errors.js';
import { assertCents, assertCurrency } from './money.js';

/**
 * Dominio puro del carrito. Todas las funciones son inmutables: reciben un
 * carrito y devuelven uno nuevo. No tocan red, base de datos ni reloj, así que
 * son triviales de testear y de reutilizar en cualquier capa.
 *
 * Forma de un carrito:
 *   { id, currency, lines: [{ sku, name, unitPriceCents, quantity }], version }
 */

export const DEFAULT_LIMITS = Object.freeze({
  /** Máximo de líneas (SKUs distintos) por carrito: acota tamaño de documento. */
  maxLines: 100,
  /** Máximo de unidades de un mismo SKU. */
  maxQuantityPerLine: 99,
});

const CART_ID_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

/** @param {object} params @returns {Readonly<object>} */
export function createCart({ id, currency }) {
  if (typeof id !== 'string' || !CART_ID_PATTERN.test(id)) {
    throw new CartError(ErrorCodes.INVALID_CART_ID, 'cart id must be 1-128 chars [A-Za-z0-9_-]');
  }
  return freeze({ id, currency: assertCurrency(currency), lines: [], version: 0 });
}

/** @param {unknown} quantity @param {typeof DEFAULT_LIMITS} limits */
function assertQuantity(quantity, limits) {
  if (!Number.isSafeInteger(quantity) || quantity < 1) {
    throw new CartError(ErrorCodes.INVALID_QUANTITY, 'quantity must be a positive integer');
  }
  if (quantity > limits.maxQuantityPerLine) {
    throw new CartError(
      ErrorCodes.QUANTITY_LIMIT_EXCEEDED,
      `quantity cannot exceed ${limits.maxQuantityPerLine} per item`,
    );
  }
}

/** @param {{sku?: unknown, name?: unknown, unitPriceCents?: unknown, currency?: unknown}} product */
function assertProduct(product) {
  if (!product || typeof product.sku !== 'string' || product.sku.length === 0) {
    throw new CartError(ErrorCodes.INVALID_PRODUCT, 'product.sku is required');
  }
  if (typeof product.name !== 'string' || product.name.length === 0) {
    throw new CartError(ErrorCodes.INVALID_PRODUCT, 'product.name is required');
  }
  assertCents(product.unitPriceCents, 'product.unitPriceCents');
}

/**
 * Añade un producto (o incrementa su cantidad si ya está). El precio y el nombre
 * de la línea se refrescan con los del producto recibido.
 * @param {ReturnType<typeof createCart>} cart
 * @param {{sku: string, name: string, unitPriceCents: number, currency: string}} product
 * @param {number} [quantity=1]
 * @param {typeof DEFAULT_LIMITS} [limits=DEFAULT_LIMITS]
 */
export function addItem(cart, product, quantity = 1, limits = DEFAULT_LIMITS) {
  assertProduct(product);
  assertQuantity(quantity, limits);
  if (product.currency !== cart.currency) {
    throw new CartError(
      ErrorCodes.CURRENCY_MISMATCH,
      `product currency ${product.currency} does not match cart currency ${cart.currency}`,
    );
  }

  const index = cart.lines.findIndex((line) => line.sku === product.sku);
  const line = {
    sku: product.sku,
    name: product.name,
    unitPriceCents: product.unitPriceCents,
    quantity: 0,
  };

  if (index === -1) {
    if (cart.lines.length >= limits.maxLines) {
      throw new CartError(ErrorCodes.CART_FULL, `cart cannot hold more than ${limits.maxLines} lines`);
    }
    line.quantity = quantity;
    return withLines(cart, [...cart.lines, line]);
  }

  line.quantity = cart.lines[index].quantity + quantity;
  assertQuantity(line.quantity, limits);
  const lines = cart.lines.slice();
  lines[index] = line;
  return withLines(cart, lines);
}

/**
 * Fija la cantidad exacta de un SKU. Cantidad 0 equivale a eliminarlo.
 * @param {ReturnType<typeof createCart>} cart
 * @param {string} sku
 * @param {number} quantity
 * @param {typeof DEFAULT_LIMITS} [limits=DEFAULT_LIMITS]
 */
export function setQuantity(cart, sku, quantity, limits = DEFAULT_LIMITS) {
  if (quantity === 0) return removeItem(cart, sku);
  assertQuantity(quantity, limits);
  const index = cart.lines.findIndex((line) => line.sku === sku);
  if (index === -1) {
    throw new CartError(ErrorCodes.ITEM_NOT_FOUND, `sku ${sku} is not in the cart`);
  }
  const lines = cart.lines.slice();
  lines[index] = { ...lines[index], quantity };
  return withLines(cart, lines);
}

/**
 * Elimina un SKU. Es idempotente: si no existe, devuelve el mismo carrito.
 * @param {ReturnType<typeof createCart>} cart
 * @param {string} sku
 */
export function removeItem(cart, sku) {
  if (!cart.lines.some((line) => line.sku === sku)) return cart;
  return withLines(cart, cart.lines.filter((line) => line.sku !== sku));
}

/** @param {ReturnType<typeof createCart>} cart */
export function clear(cart) {
  return withLines(cart, []);
}

/**
 * Subtotal sin descuentos ni impuestos, en céntimos.
 * @param {{lines: Array<{unitPriceCents: number, quantity: number}>}} cart
 */
export function subtotalCents(cart) {
  let total = 0;
  for (const line of cart.lines) {
    total += line.unitPriceCents * line.quantity;
    if (!Number.isSafeInteger(total)) {
      throw new CartError(ErrorCodes.INVALID_AMOUNT, 'cart total exceeds safe integer range');
    }
  }
  return total;
}

/** @param {{lines: Array<{quantity: number}>}} cart */
export function itemCount(cart) {
  return cart.lines.reduce((sum, line) => sum + line.quantity, 0);
}

function withLines(cart, lines) {
  return freeze({ ...cart, lines: freezeArray(lines) });
}

function freeze(obj) {
  return Object.freeze(obj);
}

function freezeArray(arr) {
  return Object.freeze(arr.map((item) => Object.freeze({ ...item })));
}

import { CartError, ErrorCodes } from './errors.js';
import { applyBps, assertCents } from './money.js';
import { itemCount, subtotalCents } from './cart.js';

/**
 * Motor de precios. Un cálculo es: subtotal → descuentos en cadena → impuestos.
 *
 * Una regla de descuento es un objeto `{ name, amount(cart, context) }` que
 * devuelve los céntimos a descontar sobre el subtotal original. El motor limita
 * cada descuento al importe restante, así nunca se puede dejar un total negativo.
 * Añadir una promoción nueva = añadir una regla; no hay que tocar el motor.
 */

/**
 * Descuento porcentual sobre las líneas de un SKU concreto.
 * @param {{sku: string, percentBps: number, name?: string}} options  1 bp = 0.01%
 */
export function percentOffSku({ sku, percentBps, name = `${percentBps / 100}% off ${sku}` }) {
  assertBps(percentBps);
  return {
    name,
    amount(cart) {
      const base = cart.lines
        .filter((line) => line.sku === sku)
        .reduce((sum, line) => sum + line.unitPriceCents * line.quantity, 0);
      return applyBps(base, percentBps);
    },
  };
}

/**
 * Descuento porcentual sobre el carrito completo si se supera un mínimo.
 * @param {{minSubtotalCents: number, percentBps: number, name?: string}} options
 */
export function percentOffCart({ minSubtotalCents, percentBps, name }) {
  assertBps(percentBps);
  assertCents(minSubtotalCents, 'minSubtotalCents');
  return {
    name: name ?? `${percentBps / 100}% off orders over ${minSubtotalCents}`,
    amount(cart) {
      const subtotal = subtotalCents(cart);
      return subtotal >= minSubtotalCents ? applyBps(subtotal, percentBps) : 0;
    },
  };
}

/**
 * Descuento fijo si se supera un mínimo de subtotal.
 * @param {{minSubtotalCents: number, amountCents: number, name?: string}} options
 */
export function fixedOffCart({ minSubtotalCents, amountCents, name }) {
  assertCents(minSubtotalCents, 'minSubtotalCents');
  assertCents(amountCents, 'amountCents');
  return {
    name: name ?? `${amountCents} off orders over ${minSubtotalCents}`,
    amount(cart) {
      return subtotalCents(cart) >= minSubtotalCents ? amountCents : 0;
    },
  };
}

/**
 * Descuento "lleva N, paga M" sobre un SKU (p. ej. 3x2).
 * @param {{sku: string, buy: number, pay: number, name?: string}} options
 */
export function buyXPayY({ sku, buy, pay, name }) {
  if (!Number.isSafeInteger(buy) || !Number.isSafeInteger(pay) || pay < 0 || buy <= pay) {
    throw new CartError(ErrorCodes.INVALID_RULE, 'buyXPayY requires integers with buy > pay >= 0');
  }
  return {
    name: name ?? `buy ${buy} pay ${pay} on ${sku}`,
    amount(cart) {
      const line = cart.lines.find((l) => l.sku === sku);
      if (!line) return 0;
      const freeUnits = Math.floor(line.quantity / buy) * (buy - pay);
      return freeUnits * line.unitPriceCents;
    },
  };
}

/**
 * Calcula el desglose completo de un carrito.
 * Es puro: no persiste nada, así que puede ejecutarse en cualquier nodo.
 *
 * @param {object} cart
 * @param {{rules?: Array<{name: string, amount: Function}>, taxRateBps?: number}} [config]
 * @returns {{
 *   currency: string, itemCount: number, subtotalCents: number,
 *   discounts: Array<{name: string, amountCents: number}>, discountCents: number,
 *   taxableCents: number, taxRateBps: number, taxCents: number, totalCents: number
 * }}
 */
export function calculateTotals(cart, { rules = [], taxRateBps = 0 } = {}) {
  assertBps(taxRateBps);
  const subtotal = subtotalCents(cart);
  let remaining = subtotal;
  const discounts = [];

  for (const rule of rules) {
    if (remaining === 0) break;
    const raw = rule.amount(cart);
    const applied = Math.min(Math.max(0, Math.floor(raw)), remaining);
    if (applied > 0) {
      discounts.push({ name: rule.name, amountCents: applied });
      remaining -= applied;
    }
  }

  const discountCents = subtotal - remaining;
  const taxableCents = remaining;
  const taxCents = applyBps(taxableCents, taxRateBps);

  return {
    currency: cart.currency,
    itemCount: itemCount(cart),
    subtotalCents: subtotal,
    discounts,
    discountCents,
    taxableCents,
    taxRateBps,
    taxCents,
    totalCents: taxableCents + taxCents,
  };
}

function assertBps(value) {
  if (!Number.isSafeInteger(value) || value < 0 || value > 10000) {
    throw new CartError(ErrorCodes.INVALID_RULE, 'basis points must be an integer in [0, 10000]');
  }
}

import { CartError, ErrorCodes } from './errors.js';

/**
 * Contrato de persistencia. Cualquier backend (Redis, DynamoDB, PostgreSQL...)
 * debe cumplir esta interfaz; el servicio no sabe nada del almacenamiento.
 *
 *   get(id)        -> Promise<cart | null>
 *   create(cart)   -> Promise<cart>            (falla si ya existe)
 *   save(cart)     -> Promise<cart>            (cart.version debe coincidir con la almacenada)
 *
 * `save` implementa control de concurrencia optimista: solo escribe si la
 * versión almacenada es la que el cliente leyó; si no, lanza CONCURRENCY_CONFLICT
 * y el servicio reintenta. Así varias instancias pueden atender el mismo carrito
 * sin bloqueos distribuidos.
 *
 * Equivalente SQL de referencia:
 *   UPDATE carts SET lines = $1, version = version + 1
 *    WHERE id = $2 AND version = $3;   -- 0 filas => CONCURRENCY_CONFLICT
 */
export class InMemoryCartRepository {
  /** @type {Map<string, object>} */
  #carts = new Map();

  async get(id) {
    return this.#carts.get(id) ?? null;
  }

  async create(cart) {
    if (this.#carts.has(cart.id)) {
      throw new CartError(ErrorCodes.CART_ALREADY_EXISTS, `cart ${cart.id} already exists`);
    }
    const stored = Object.freeze({ ...cart, version: 0 });
    this.#carts.set(cart.id, stored);
    return stored;
  }

  async save(cart) {
    // Todo lo que hay entre el get y el set de este método es síncrono, así que
    // es atómico respecto a otras llamadas en el mismo proceso.
    const current = this.#carts.get(cart.id);
    if (!current) {
      throw new CartError(ErrorCodes.CART_NOT_FOUND, `cart ${cart.id} not found`);
    }
    if (current.version !== cart.version) {
      throw new CartError(ErrorCodes.CONCURRENCY_CONFLICT, `cart ${cart.id} was modified concurrently`);
    }
    const stored = Object.freeze({ ...cart, version: cart.version + 1 });
    this.#carts.set(cart.id, stored);
    return stored;
  }
}

/**
 * Bus de eventos en memoria. Sirve para desacoplar efectos secundarios
 * (analítica, invalidación de caché, notificaciones) de la lógica del carrito.
 * En producción, un adaptador puede reenviar los mismos eventos a una cola
 * (Kafka, SQS, Redis Streams) sin cambiar a quien emite.
 */
export class EventBus {
  /** @type {Map<string, Set<Function>>} */
  #listeners = new Map();

  /**
   * @param {string} type
   * @param {(payload: any) => void | Promise<void>} handler
   * @returns {() => void} función para desuscribirse
   */
  on(type, handler) {
    if (!this.#listeners.has(type)) this.#listeners.set(type, new Set());
    this.#listeners.get(type).add(handler);
    return () => this.#listeners.get(type)?.delete(handler);
  }

  /**
   * Notifica a los suscriptores. Un handler que falla no afecta a los demás
   * ni a quien emitió el evento; los errores se reportan con `onError`.
   * @param {string} type
   * @param {any} payload
   */
  emit(type, payload) {
    for (const handler of this.#listeners.get(type) ?? []) {
      Promise.resolve()
        .then(() => handler(payload))
        .catch((error) => this.onError(error, type));
    }
  }

  /** @param {unknown} error @param {string} type */
  onError(error, type) {
    console.error(`[EventBus] handler for "${type}" failed:`, error);
  }
}

/**
 * Contrato de catálogo: fuente de verdad de nombre y precio de los productos.
 *
 *   getProducts(skus) -> Promise<Map<sku, {sku, name, unitPriceCents, currency}>>
 *
 * Se pide por lotes (`getProducts`) para evitar N+1 llamadas cuando el servicio
 * necesita varios SKUs. Una implementación real debería usar caché (p. ej. Redis
 * con TTL corto) delante del servicio de catálogo.
 */
export class InMemoryCatalog {
  /** @type {Map<string, object>} */
  #products = new Map();

  /** @param {Array<{sku: string, name: string, unitPriceCents: number, currency: string}>} products */
  constructor(products = []) {
    for (const product of products) this.upsert(product);
  }

  upsert(product) {
    this.#products.set(product.sku, Object.freeze({ ...product }));
  }

  async getProducts(skus) {
    const result = new Map();
    for (const sku of new Set(skus)) {
      const product = this.#products.get(sku);
      if (product) result.set(sku, product);
    }
    return result;
  }
}

